var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 14\u201321 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a01 09\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0432\u044b\u043f\u0443\u0441\u043a\u0435\u000d\u000a\u0422\u0440\u0430\u043c\u043f \u043d\u0430\u0437\u043d\u0430\u0447\u0438\u043b \u042d\u0440-\u0420\u0438\u044f\u0434 \u043e\u0441\u043e\u0431\u044b\u043c \u000d\u000a\u0441\u043e\u044e\u0437\u043d\u0438\u043a\u043e\u043c\u000d\u000a\u0421\u0428\u0410 \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u044e\u0442 \u043f\u0440\u0438\u0432\u0438\u043b\u0435\u0433\u0438\u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u0438 \u0438 \u0437\u0430\u043a\u043b\u044e\u0447\u0430\u044e\u0442 \u043a\u0440\u0443\u043f\u043d\u044b\u0435 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0435 \u000d\u000a\u0441\u0434\u0435\u043b\u043a\u0438: 48 F-35, 300 \u0442\u0430\u043d\u043a\u043e\u0432, \u043e\u0431\u0449\u0438\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b \u000d\u000a\u043e\u0442 \u0430\u0442\u043e\u043c\u043d\u043e\u0439 \u0441\u0444\u0435\u0440\u044b \u0434\u043e \u0418\u0418. \u041f\u0440\u0438\u043d\u0446 \u043f\u043e\u043e\u0431\u0435\u0449\u0430\u043b \u000d\u000a\u043d\u0430\u0440\u0430\u0441\u0442\u0438\u0442\u044c \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u0421\u0428\u0410 \u0434\u043e $1 \u0442\u0440\u043b\u043d.\u000d\u000aEmirates \u0432\u043b\u043e\u0436\u0438\u0442 \u0434\u043e $12 \u043c\u043b\u0440\u0434 \u0432 \u043d\u043e\u0432\u044b\u0439 \u000d\u000a\u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442 \u0414\u0443\u0431\u0430\u044f\u000d\u000a\u041f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u041e\u0410\u042d \u0443\u0436\u0435 \u0432\u044b\u0434\u0435\u043b\u0438\u043b\u043e \u000d\u000a\u043d\u0430 \u0440\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044e \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442\u0430 $35 \u043c\u043b\u0440\u0434. \u000d\u000a\u0410\u0432\u0438\u0430\u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a \u0432\u043b\u043e\u0436\u0438\u0442 \u043d\u043e\u0432\u044b\u0435 \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u0432 \u0441\u0432\u043e\u044e \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443. \u041f\u0440\u043e\u0435\u043a\u0442 \u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u000d\u000a\u0438\u0437 \u0440\u0435\u0437\u0435\u0440\u0432\u043e\u0432 \u0438 \u0437\u0430\u0439\u043c\u043e\u0432, \u0431\u0435\u0437 \u0432\u044b\u0445\u043e\u0434\u0430 \u043d\u0430 \u0431\u0438\u0440\u0436\u0443. \u000d\u000a\u041d\u043e\u0432\u044b\u0439 \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442 \u0434\u043e\u043b\u0436\u0435\u043d \u0437\u0430\u043c\u0435\u043d\u0438\u0442\u044c \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0439 \u000d\u000a\u043a 2032 \u0433\u043e\u0434\u0443.\u000d\u000a\u0421\u0442\u0440\u0430\u0445\u043e\u0432\u044b\u0435 \u043f\u0440\u0435\u043c\u0438\u0438 \u0437\u0430 \u043f\u0440\u043e\u0445\u043e\u0434 \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435 \u043e\u0441\u0442\u0430\u043d\u0443\u0442\u0441\u044f \u0432\u044b\u0441\u043e\u043a\u0438\u043c\u0438\u000d\u000a\u041d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u043f\u0430\u0443\u0437\u0443 \u0432 \u0430\u0442\u0430\u043a\u0430\u0445 \u0445\u0443\u0441\u0438\u0442\u043e\u0432, \u0440\u044b\u043d\u043e\u043a \u000d\u000a\u043d\u0435 \u0432\u0435\u0440\u0438\u0442 \u0432 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c. \u0412 \u0442\u043e \u0436\u0435 \u0432\u0440\u0435\u043c\u044f \u000d\u000a\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0435 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u0435 \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e \u000d\u000a\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u043e\u0442\u0440\u0430\u0441\u043b\u0438.\u000d\u000aAD Ports \u043f\u043e\u043a\u0430\u0437\u0430\u043b \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u0443\u044e \u0432\u044b\u0440\u0443\u0447\u043a\u0443\u000d\u000a\u0417\u0430 \u0434\u0435\u0432\u044f\u0442\u044c \u043c\u0435\u0441\u044f\u0446\u0435\u0432 \u0434\u043e\u0445\u043e\u0434\u044b \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0438\u0441\u044c\u2028\u000d\u000a\u0434\u043e $1,47 \u043c\u043b\u0440\u0434, \u0430 \u0447\u0438\u0441\u0442\u0430\u044f \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u0434\u043e $409 \u043c\u043b\u043d. \u000d\u000a\u0412 III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 \u0440\u043e\u0441\u0442 \u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u0434\u043e\u0441\u0442\u0438\u0433 34%.\u000d\u000aGanfeng Lithium \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0438\u0440\u0443\u0435\u0442 \u0440\u043e\u0441\u0442 \u000d\u000a\u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043b\u0438\u0442\u0438\u0439 \u0432 2026 \u0433\u043e\u0434\u0443\u000d\u000a\u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0432\u0441\u0435 \u0440\u0430\u0432\u043d\u043e \u043e\u043f\u0435\u0440\u0435\u0434\u0438\u0442 \u000d\u000a\u0441\u043f\u0440\u043e\u0441, \u043d\u043e \u0446\u0435\u043d\u044b \u043c\u043e\u0433\u0443\u0442 \u043f\u043e\u0434\u0441\u043a\u043e\u0447\u0438\u0442\u044c \u0434\u043e $21\u201328 \u0442\u044b\u0441. \u000d\u000a\u0437\u0430 \u0442\u043e\u043d\u043d\u0443. \u0420\u043e\u0441\u0442 \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u0430 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u0435\u0439 \u0443\u0436\u0435 \u000d\u000a\u043f\u043e\u0432\u044b\u0441\u0438\u043b \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u044b \u043d\u0430 2025 \u0433\u043e\u0434.\u000d\u000a\u00ab\u0420\u0443\u0441\u0430\u043b\u00bb \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0439 \u0437\u0430\u0432\u043e\u0434 \u000d\u000a\u0432 \u042d\u0444\u0438\u043e\u043f\u0438\u0438 \u0437\u0430 $1 \u043c\u043b\u0440\u0434\u000d\u000a\u041f\u0440\u043e\u0435\u043a\u0442 \u043d\u0430 70% \u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0437\u0430 \u0441\u0447\u0435\u0442 \u0437\u0430\u0435\u043c\u043d\u044b\u0445 \u000d\u000a\u0441\u0440\u0435\u0434\u0441\u0442\u0432, \u0437\u0430\u043f\u0443\u0441\u043a \u0437\u0430\u0439\u043c\u0435\u0442 3\u20134 \u0433\u043e\u0434\u0430. \u041c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u000d\u000a500 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u0433\u043e\u0434.\u000d\u000a\u0421\u0428\u0410 \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u043b\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0442\u043e\u043f\u043e\u0432\u044b\u0445 \u000d\u000a\u0447\u0438\u043f\u043e\u0432 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c G42 \u0438 Humain \u0434\u0430\u0434\u0443\u0442 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438, \u000d\u000a\u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u044b\u0435 \u0441 35 \u0442\u044b\u0441. \u0447\u0438\u043f\u043e\u0432 Nvidia Blackwell. \u000d\u000a\u042d\u0442\u043e \u0437\u0430\u043c\u0435\u0442\u043d\u044b\u0439 \u0441\u0434\u0432\u0438\u0433 \u043f\u043e\u0441\u043b\u0435 \u0436\u0435\u0441\u0442\u043a\u0438\u0445 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0445 \u000d\u000a\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0435\u0439 \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438.\u000d\u000a\u041a\u043e\u043d\u0433\u0440\u0435\u0441\u0441 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043e\u0431\u044a\u044f\u0441\u043d\u0435\u043d\u0438\u0439 \u043e\u0442 Morgan \u000d\u000aStanley \u043f\u043e IPO Zijin Gold\u000d\u000a\u0411\u0430\u043d\u043a \u043f\u043e\u0434\u043e\u0437\u0440\u0435\u0432\u0430\u044e\u0442 \u0432 \u043e\u0431\u0445\u043e\u0434\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439 \u000d\u000a\u0432 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0438 \u043c\u0430\u0442\u0435\u0440\u0438\u043d\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438, \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0435\u043d\u043d\u043e\u0439 \u0432 \u0447\u0435\u0440\u043d\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u0421\u0428\u0410. \u041a\u043e\u043c\u0438\u0442\u0435\u0442 \u000d\u000a\u0437\u0430\u043f\u0440\u043e\u0441\u0438\u043b \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b \u0438 \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u043a\u0443, \u0441\u0440\u043e\u043a \u000d\u000a\u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0434\u043e 27 \u043d\u043e\u044f\u0431\u0440\u044f.\u000d\u000a\u041d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u000d\u000a\u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440\u0430 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0438 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u000d\u000a\u0421\u043f\u0440\u043e\u0441 \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0430\u0432\u0442\u043e\u043f\u0440\u043e\u043c\u0430 \u043f\u0430\u0434\u0430\u0435\u0442, \u0440\u0438\u0441\u043a \u000d\u000a\u043f\u0435\u0440\u0435\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0440\u0430\u0441\u0442\u0435\u0442. \u0414\u043e\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u2028\u000d\u000aLFP-\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u0440\u0443\u0448\u0438\u0442 \u043f\u0440\u0435\u0436\u043d\u0438\u0435 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u044b.\u000d\u000aGlencore \u043c\u043e\u0436\u0435\u0442 \u0432\u043b\u043e\u0436\u0438\u0442\u044c\u0441\u044f \u0432 IPO \u000d\u000aChuangxin Industries\u000d\u000a\u0412 \u0441\u0434\u0435\u043b\u043a\u0435 \u0433\u043e\u0442\u043e\u0432\u044b \u0443\u0447\u0430\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u044b \u000d\u000a\u0432\u044b\u043a\u0443\u043f\u0438\u0442\u044c \u0434\u043e \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u044b \u0432\u044b\u043f\u0443\u0441\u043a\u0430. \u041e\u0431\u044a\u0435\u043c IPO \u000d\u000a\u043c\u043e\u0436\u0435\u0442 \u0434\u043e\u0441\u0442\u0438\u0447\u044c $700 \u043c\u043b\u043d.","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 14\u201321 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u0422\u0440\u0430\u043c\u043f \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u0438\u043b \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u0441\u0442\u0430\u0442\u0443\u0441 \u000d\u000a\u043e\u0441\u043e\u0431\u043e\u0433\u043e \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0430\u000d\u000a\u041a\u0440\u043e\u043c\u0435 \u0432\u043e\u0435\u043d\u043d\u043e\u0433\u043e \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u0441\u0442\u0440\u0430\u043d\u044b \u0442\u0430\u043a\u0436\u0435 \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u043e \u043f\u0430\u0440\u0442\u043d\u0435\u0440\u0441\u0442\u0432\u0435 \u0432 \u0441\u0444\u0435\u0440\u0435 \u0430\u0442\u043e\u043c\u043d\u043e\u0439 \u000d\u000a\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438, \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044f \u0418\u0418 \u0438 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u043c\u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u0430\u043c\u0438.\u000d\u000a\u0414\u043e\u043d\u0430\u043b\u044c\u0434 \u0422\u0440\u0430\u043c\u043f \u0440\u0430\u0441\u0448\u0438\u0440\u0438\u043b \u0432\u043e\u0435\u043d\u043d\u044b\u0435 \u000d\u000a\u0438 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u0438\u0432\u0438\u043b\u0435\u0433\u0438\u0438 \u0434\u043b\u044f \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u0438. \u0421\u0442\u043e\u0440\u043e\u043d\u044b \u0437\u0430\u043a\u043b\u044e\u0447\u0438\u043b\u0438 \u043a\u0440\u0443\u043f\u043d\u044b\u0435 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0435 \u000d\u000a\u0438 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u043f\u0440\u043e\u0434\u0430\u0436\u0443 \u000d\u000a48 \u0438\u0441\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0435\u0439 F-35 \u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0443 \u000d\u000a300 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0445 \u0442\u0430\u043d\u043a\u043e\u0432. \u041e\u043d \u043e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a\u0432\u043e \u0432\u0440\u0435\u043c\u044f \u0432\u0438\u0437\u0438\u0442\u0430 \u043d\u0430\u0441\u043b\u0435\u0434\u043d\u043e\u0433\u043e \u043f\u0440\u0438\u043d\u0446\u0430 \u041c\u0443\u0445\u0430\u043c\u043c\u0435\u0434\u0430 \u000d\u000a\u0431\u0435\u043d \u0421\u0430\u043b\u044c\u043c\u0430\u043d\u0430 \u0432 \u0411\u0435\u043b\u044b\u0439 \u0434\u043e\u043c.\u000d\u000a\u043e\u0431\u044a\u044f\u0432\u0438\u043b\u000d\u000a\u041d\u0430\u0441\u043b\u0435\u0434\u043d\u044b\u0439 \u043f\u0440\u0438\u043d\u0446 \u0441\u043e\u043e\u0431\u0449\u0438\u043b \u043e \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0438\u0438 \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u0441\u0432\u043e\u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u0421\u0428\u0410 \u0441 $600 \u043c\u043b\u0440\u0434 \u000d\u000a\u0434\u043e $1 \u0442\u0440\u043b\u043d, \u043e\u0434\u043d\u0430\u043a\u043e \u043d\u0435 \u0443\u0442\u043e\u0447\u043d\u0438\u043b \u0441\u0440\u043e\u043a\u0438 \u0438 \u0434\u0435\u0442\u0430\u043b\u0438. \u000d\u000a\u041f\u043e\u0441\u0442\u0430\u0432\u043a\u0430 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u0438\u0441\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0435\u0439 \u000d\u000aF-35 \u043f\u0440\u0438\u0432\u0435\u0434\u0435\u0442 \u043a \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f\u043c \u0432 \u0431\u0430\u043b\u0430\u043d\u0441\u0435 \u000d\u000a\u0432\u043e\u0435\u043d\u043d\u044b\u0445 \u0441\u0438\u043b \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435. \u0414\u043e \u0441\u0438\u0445 \u043f\u043e\u0440 \u000d\u000a\u0418\u0437\u0440\u0430\u0438\u043b\u044c \u0431\u044b\u043b \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u043e\u043c \u000d\u000a\u0440\u0435\u0433\u0438\u043e\u043d\u0430, \u0440\u0430\u0441\u043f\u043e\u043b\u0430\u0433\u0430\u044e\u0449\u0438\u043c \u0442\u0430\u043a\u0438\u043c\u0438 \u0441\u0430\u043c\u043e\u043b\u0435\u0442\u0430\u043c\u0438.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000a\u0418\u043d\u0434\u0438\u0439\u0441\u043a\u0430\u044f Vedanta \u043d\u0430\u0440\u0430\u0441\u0442\u0438\u0442 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0438\u0439 \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u0441\u0435\u043a\u0442\u043e\u0440 \u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0430 \u043a 2030 \u0433\u043e\u0434\u0443 \u0447\u0435\u0442\u044b\u0440\u0435\u0445\u043a\u0440\u0430\u0442\u043d\u043e \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u0432\u043a\u043b\u0430\u0434 \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u0432 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0443 \u0438 \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u044c \u0432 \u043d\u0435\u0435 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438.\u000d\u000a\u0418\u043d\u0434\u0438\u0439\u0441\u043a\u0438\u0439 \u043a\u043e\u043d\u0433\u043b\u043e\u043c\u0435\u0440\u0430\u0442 Vedanta \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0443 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438. \u000d\u000aVedanta \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0430 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044e \u0438 \u043d\u0430\u0447\u043d\u0435\u0442 \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u000d\u000a\u043d\u0430 \u043c\u0435\u0434\u043d\u044b\u0445 \u0438 \u0437\u043e\u043b\u043e\u0442\u044b\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u0445 \u000d\u000a\u0432 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0438\u0435 \u0448\u0435\u0441\u0442\u044c-\u0432\u043e\u0441\u0435\u043c\u044c \u043c\u0435\u0441\u044f\u0446\u0435\u0432. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a \u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u043e \u043c\u0435\u0434\u043d\u043e\u043c\u0443 \u2028\u000d\u000a\u0438 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u043c\u0443 \u0431\u0438\u0437\u043d\u0435\u0441\u0443 \u041f\u0443\u043d\u0438\u0442 \u041a\u0443\u0440\u0430\u043d\u0430.\u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u000d\u000a\u041a\u043e\u043d\u0433\u043b\u043e\u043c\u0435\u0440\u0430\u0442 \u0442\u0430\u043a\u0436\u0435 \u043d\u0430\u043c\u0435\u0440\u0435\u043d \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u043d\u043e\u0432\u044b\u0435 \u000d\u000a\u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u0438 \u0432\u044b\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u0432 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0435 \u043f\u043e\u043b\u043d\u0443\u044e \u000d\u000a\u0446\u0435\u043f\u043e\u0447\u043a\u0443 \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044f \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u0434\u043e\u0431\u044b\u0447\u0438 \u000d\u000a\u0434\u043e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432. Vedanta \u0443\u0436\u0435 \u043d\u0430\u0447\u0430\u043b\u0430 \u000d\u000a\u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0435 \u043e\u0431\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u044f \u043f\u043e \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044e \u000d\u000a\u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0434\u043b\u044f \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u0432 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u0438.\u000d\u000a02 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 14\u201321 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442 #\u0430\u0432\u0438\u0430\u0446\u0438\u044f\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f \u0430\u0432\u0438\u0430\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Gulf Air \u043a\u0443\u043f\u0438\u0442 \u043f\u0430\u0440\u0442\u0438\u044e \u000d\u000aBoeing 787 Dreamliner\u000d\u000a\u0421\u0443\u043c\u043c\u0430 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430 \u043c\u0435\u0436\u0434\u0443 Gulf Air \u0438 Boeing \u043d\u0435 \u0440\u0430\u0441\u043a\u0440\u044b\u0432\u0430\u0435\u0442\u0441\u044f. \u0411\u0435\u043b\u044b\u0439 \u0434\u043e\u043c \u0440\u0430\u043d\u0435\u0435 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u043b \u0441\u0434\u0435\u043b\u043a\u0443 \u000d\u000a\u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0432 $7 \u043c\u043b\u0440\u0434. \u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0438\u0439 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a \u2028\u000d\u000aGulf Air \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u000d\u000a\u0441 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u043c \u0430\u0432\u0438\u0430\u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u000d\u000a\u043a\u043e\u043d\u0446\u0435\u0440\u043d\u043e\u043c Boeing \u043d\u0430 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0443 \u043e\u0442 12 \u0434\u043e 15 \u000d\u000a\u0441\u0430\u043c\u043e\u043b\u0435\u0442\u043e\u0432 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 787 Dreamliner. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a \u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u0430\u0432\u0438\u0430\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438.\u000a\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u2014 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u0435\u0439 \u000d\u000a\u043f\u0440\u0438\u043d\u0446\u0430 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0421\u0430\u043b\u044c\u043c\u0430\u043d\u0430 \u0431\u0435\u043d \u0425\u0430\u043c\u0430\u0434\u0430 \u000d\u000a\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f\u000d\u000a\u0431\u0435\u043d \u0418\u0441\u044b \u0410\u043b\u044c \u0425\u0430\u043b\u0438\u0444\u044b \u0432 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d\u0435 \u0438 \u0447\u0430\u0441\u0442\u044c \u000d\u000a\u0431\u043e\u043b\u0435\u0435 \u0448\u0438\u0440\u043e\u043a\u043e\u0433\u043e \u043f\u0430\u043a\u0435\u0442\u0430 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0432 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0443\u044e \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0443 \u000d\u000a\u043e\u0431\u044a\u0435\u043c\u043e\u043c \u043e\u043a\u043e\u043b\u043e $17 \u043c\u043b\u0440\u0434. \u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d \u000d\u000a\u043d\u0430 \u043f\u043e\u043b\u044f\u0445 Dubai Airshow \u2014 \u043e\u0434\u043d\u043e\u0439 \u0438\u0437 \u0432\u0435\u0434\u0443\u0449\u0438\u0445 \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0430\u0432\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u0432\u044b\u0441\u0442\u0430\u0432\u043e\u043a.\u000d\u000a#\u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442 #\u0430\u0432\u0438\u0430\u0446\u0438\u044f\u000d\u000aEmirates \u0432\u043b\u043e\u0436\u0438\u0442 \u0434\u043e $12 \u043c\u043b\u0440\u0434 \u0432 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u2028\u000d\u000a\u043d\u043e\u0432\u043e\u0433\u043e \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442\u0430 \u0432 \u0414\u0443\u0431\u0430\u0435\u000d\u000a\u0420\u0430\u043d\u0435\u0435 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u041e\u0410\u042d \u0432\u044b\u0434\u0435\u043b\u0438\u043b\u043e \u043d\u0430 \u0440\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044e \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442\u0430 $35 \u043c\u043b\u0440\u0434. \u0410\u0432\u0438\u0430\u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a \u000d\u000a\u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0432\u043b\u043e\u0436\u0438\u0442\u044c \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u0432 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443. \u000d\u000aEmirates \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 \u043e\u0442 $10 \u043c\u043b\u0440\u0434 \u0434\u043e $12 \u043c\u043b\u0440\u0434 \u000d\u000a\u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u043d\u043e\u0432\u043e\u0433\u043e \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442\u0430 \u000d\u000a\u0410\u043b\u044c \u041c\u0430\u043a\u0442\u0443\u043c, \u0433\u043b\u0430\u0432\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0448\u0435\u0439\u0445 \u000d\u000a\u0410\u0445\u043c\u0435\u0434 \u0431\u0435\u043d \u0421\u0430\u0438\u0434 \u0410\u043b\u044c \u041c\u0430\u043a\u0442\u0443\u043c. \u0421\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u000d\u000a\u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u043e\u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u0437\u0430 \u0441\u0447\u0435\u0442 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u000d\u000a\u0440\u0435\u0437\u0435\u0440\u0432\u043e\u0432 \u0430\u0432\u0438\u0430\u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a\u0430 \u0438 \u0437\u0430\u0438\u043c\u0441\u0442\u0432\u043e\u0432\u0430\u043d\u0438\u0439.\u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u000d\u000a\u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0433\u043e \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u0430\u043a\u0446\u0438\u0439 \u000d\u000a\u043d\u0435 \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442\u0441\u044f.\u000a\u000d\u000a\u0410\u044d\u0440\u043e\u043f\u043e\u0440\u0442 \u0410\u043b\u044c \u041c\u0430\u043a\u0442\u0443\u043c \u0437\u0430\u043c\u0435\u043d\u0438\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u000d\u000a\u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0439 \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442 \u0414\u0443\u0431\u0430\u044f \u043a 2032 \u0433\u043e\u0434\u0443 \u000d\u000a\u0438 \u0441\u043c\u043e\u0436\u0435\u0442 \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u043e \u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u0442\u044c \u0434\u043e 260 \u043c\u043b\u043d \u000d\u000a\u043f\u0430\u0441\u0441\u0430\u0436\u0438\u0440\u043e\u0432 \u043a 2057 \u0433\u043e\u0434\u0443.\u000d\u000a03 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 14\u201321 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000aAD Ports \u0438 CMA CGM \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u0442 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043d\u044b\u0439 \u000d\u000a\u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b \u0432 \u043f\u043e\u0440\u0442\u0443 \u0425\u0430\u043b\u0438\u0444\u0430 \u0437\u0430 $115 \u043c\u043b\u043d\u000d\u000a\u0422\u0435\u0440\u043c\u0438\u043d\u0430\u043b CMA Terminals Khalifa Port \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d \u0432 \u0433\u043b\u0430\u0432\u043d\u043e\u043c \u043f\u043e\u0440\u0442\u0443 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u043d\u0430 \u0431\u0435\u0440\u0435\u0433\u0443 \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430. \u041e\u043d \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 CMA CGM \u043d\u0430 70% \u0438 AD Ports \u043d\u0430 30%. \u000d\u000a\u0422\u0435\u0440\u043c\u0438\u043d\u0430\u043b \u0438\u0441\u043f\u044b\u0442\u044b\u0432\u0430\u0435\u0442 \u0432\u044b\u0441\u043e\u043a\u0443\u044e \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0443 \u000d\u000a\u0441 \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u0432 \u0434\u0435\u043a\u0430\u0431\u0440\u0435 2024 \u0433\u043e\u0434\u0430. \u000d\u000a\u0420\u0430\u0441\u0445\u043e\u0434\u044b \u043d\u0430 \u043f\u0440\u043e\u0435\u043a\u0442 \u043f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b \u0434\u043e\u043b\u044f\u043c \u000d\u000a\u0432\u043b\u0430\u0434\u0435\u043d\u0438\u044f, \u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 AD Ports. \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f\u000d\u000a\u0420\u0430\u0431\u043e\u0442\u044b \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044c \u0432 \u043d\u0430\u0447\u0430\u043b\u0435 \u000d\u000a2028 \u0433\u043e\u0434\u0430. \u041c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u0430 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u0441\u044f \u000d\u000a\u0434\u043e 2,7 \u043c\u043b\u043d TEU \u0432 \u0433\u043e\u0434 (+50%), \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u043d\u0430\u044f \u000d\u000a\u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0440\u0442\u0430 \u0425\u0430\u043b\u0438\u0444\u0430 \u2014 \u0434\u043e 10,5 \u043c\u043b\u043d TEU \u000d\u000a(+9%).\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000aAD Ports \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u0443\u044e \u0432\u044b\u0440\u0443\u0447\u043a\u0443 \u000d\u000a\u0441 \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u0432\u044b\u0445\u043e\u0434\u0430 \u043d\u0430 \u0431\u0438\u0440\u0436\u0443\u000d\u000a\u0417\u0430 \u043f\u0435\u0440\u0432\u044b\u0435 \u0434\u0435\u0432\u044f\u0442\u044c \u043c\u0435\u0441\u044f\u0446\u0435\u0432 2025 \u0433\u043e\u0434\u0430 \u0447\u0438\u0441\u0442\u0430\u044f \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 $409,26 \u043c\u043b\u043d (+17%).\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u044d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u043e\u0433\u043e \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 AD Ports Group \u0432 III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 \u000d\u000a2025 \u0433\u043e\u0434\u0430 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0443\u0440\u043e\u0432\u043d\u044f \u000d\u000a\u0441 \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u043b\u0438\u0441\u0442\u0438\u043d\u0433\u0430 \u043d\u0430 \u0444\u043e\u043d\u0434\u043e\u0432\u043e\u0439 \u0431\u0438\u0440\u0436\u0435 \u2028\u000d\u000a\u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u0432 \u0444\u0435\u0432\u0440\u0430\u043b\u0435 2022 \u0433\u043e\u0434\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a \u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438.\u000a\u000d\u000a\u0417\u0430 \u043e\u0442\u0447\u0435\u0442\u043d\u044b\u0439 \u043f\u0435\u0440\u0438\u043e\u0434 \u0432\u044b\u0440\u0443\u0447\u043a\u0430 AD Ports \u000d\u000a\u0432 \u0433\u043e\u0434\u043e\u0432\u043e\u043c \u0432\u044b\u0440\u0430\u0436\u0435\u043d\u0438\u0438 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0430 $1,47 \u043c\u043b\u0440\u0434 \u000d\u000a(+16%), \u0447\u0438\u0441\u0442\u0430\u044f \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u0432 III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 \u2014 \u2028\u000d\u000a$162,4 \u043c\u043b\u043d (+34%).\u000d\u000a\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f\u000d\u000a04 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 14\u201321 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u00ab\u0420\u0443\u0441\u0430\u043b\u00bb \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442 \u0432 \u042d\u0444\u0438\u043e\u043f\u0438\u0438 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0439 \u0437\u0430\u0432\u043e\u0434 \u000d\u000a\u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e \u0441 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u043c \u0444\u043e\u043d\u0434\u043e\u043c \u0441\u0442\u0440\u0430\u043d\u044b\u000d\u000a\u0421\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0437\u0430\u0439\u043c\u0435\u0442 3\u20134 \u0433\u043e\u0434\u0430, \u0441\u0440\u043e\u043a \u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u0438 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u2014 \u0434\u043e 50 \u043b\u0435\u0442.\u000d\u000a\u0421\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u0444\u043e\u043d\u0434 \u042d\u0444\u0438\u043e\u043f\u0438\u0438 Ethiopian \u000d\u000aInvestment Holdings \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b \u0441 \u00ab\u0420\u0443\u0441\u0430\u043b\u043e\u043c\u00bb \u000d\u000a\u043c\u0435\u043c\u043e\u0440\u0430\u043d\u0434\u0443\u043c \u043e \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0435 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u043e\u0433\u043e \u000d\u000a\u0437\u0430\u0432\u043e\u0434\u0430 \u0432 \u0430\u0444\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0441\u0442\u0440\u0430\u043d\u0435, \u000d\u000a\u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u0444\u043e\u043d\u0434\u0430.\u000d\u000a\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f\u000d\u000a\u0421\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u044d\u0442\u0430\u043f\u0430 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u2014 \u000d\u000a\u043e\u043a\u043e\u043b\u043e $1 \u043c\u043b\u0440\u0434, \u043d\u0430 70% \u0441\u0443\u043c\u043c\u0430 \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u0437\u0430 \u0441\u0447\u0435\u0442 \u0437\u0430\u0435\u043c\u043d\u044b\u0445 \u0441\u0440\u0435\u0434\u0441\u0442\u0432. \u000d\u000a\u041f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u043c\u044b\u0439 \u0433\u043e\u0434\u043e\u0432\u043e\u0439 \u043e\u0431\u044a\u0435\u043c \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u2014 \u000d\u000a500 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u043e\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438.\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u041f\u0440\u0435\u043c\u0438\u0438 \u0437\u0430 \u043f\u0440\u043e\u0445\u043e\u0434 \u043f\u043e \u041a\u0440\u0430\u0441\u043d\u043e\u043c\u0443 \u043c\u043e\u0440\u044e \u043e\u0441\u0442\u0430\u043d\u0443\u0442\u0441\u044f \u000d\u000a\u0432\u044b\u0441\u043e\u043a\u0438\u043c\u0438, \u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0443 \u043d\u0430\u043f\u0430\u0434\u0435\u043d\u0438\u0439 \u000d\u000a\u0445\u0443\u0441\u0438\u0442\u043e\u0432\u000d\u000a\u0422\u0440\u0430\u043d\u0437\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u0435\u0442 \u0434\u043e 15% \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438, \u044d\u0442\u043e \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u000d\u000a\u043c\u0435\u0436\u0434\u0443 \u0415\u0432\u0440\u043e\u043f\u043e\u0439 \u0438 \u0410\u0437\u0438\u0435\u0439. \u0412 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u043f\u043e \u043d\u0435\u043c\u0443 \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u043e \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u043b\u043e \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c 36 \u0441\u0443\u0434\u043e\u0432, \u000d\u000a\u0432\u0434\u0432\u043e\u0435 \u043c\u0435\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u0432 2023 \u0433\u043e\u0434\u0443.\u000d\u000a\u0421\u0442\u0440\u0430\u0445\u043e\u0432\u044b\u0435 \u043f\u0440\u0435\u043c\u0438\u0438 \u0434\u043b\u044f \u0441\u0443\u0434\u043e\u0432, \u043f\u0440\u043e\u0445\u043e\u0434\u044f\u0449\u0438\u0445 \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435, \u043e\u0441\u0442\u0430\u043d\u0443\u0442\u0441\u044f \u0432\u044b\u0441\u043e\u043a\u0438\u043c\u0438, \u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u000d\u000a\u043d\u0430 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u0439\u0435\u043c\u0435\u043d\u0441\u043a\u0438\u043c\u0438 \u0445\u0443\u0441\u0438\u0442\u0430\u043c\u0438 \u000d\u000a\u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043e\u0433\u043d\u044f. \u0422\u0430\u043a\u043e\u0433\u043e \u043c\u043d\u0435\u043d\u0438\u044f \u000d\u000a \u043e\u0442\u0440\u0430\u0441\u043b\u0435\u0432\u044b\u0435 \u044d\u043a\u0441\u043f\u0435\u0440\u0442\u044b, \u000d\u000a\u043e\u043f\u0440\u043e\u0448\u0435\u043d\u043d\u044b\u0435 \u0438\u0437\u0434\u0430\u043d\u0438\u0435\u043c Arabian Gulf Business \u000d\u000aInsight.\u000a\u000d\u000a\u0412\u043b\u0438\u044f\u043d\u0438\u0435 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u044f \u043d\u0430 \u0441\u0442\u0430\u0432\u043a\u0438 \u043f\u043e\u043a\u0430 \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u043e. \u000d\u000a\u0421\u0443\u0434\u043e\u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u044b \u0438 \u0441\u0442\u0440\u0430\u0445\u043e\u0432\u044b\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u043d\u0435 \u0443\u0432\u0435\u0440\u0435\u043d\u044b, \u0447\u0442\u043e \u043a\u0440\u0438\u0437\u0438\u0441 \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u043c \u043c\u043e\u0440\u0435 \u000d\u000a\u0443\u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e. \u0412 \u0442\u043e \u0436\u0435 \u0432\u0440\u0435\u043c\u044f \u000d\u000a\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0435 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u0435 \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e \u000d\u000a\u0432\u0435\u0440\u043d\u0443\u0442\u044c \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c.\u000d\u000a\u043f\u0440\u0438\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044e\u0442\u0441\u044f\u000d\u000a\u0419\u0435\u043c\u0435\u043d\u0441\u043a\u0438\u0435 \u0445\u0443\u0441\u0438\u0442\u044b \u0438\u0437 \u00ab\u0410\u043d\u0441\u0430\u0440 \u0410\u043b\u043b\u0430\u0445\u00bb \u0441 \u043d\u043e\u044f\u0431\u0440\u044f \u000d\u000a2023 \u0433\u043e\u0434\u0430 \u0430\u0442\u0430\u043a\u043e\u0432\u0430\u043b\u0438 \u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u0438\u0435 \u0441\u0443\u0434\u0430 \u000d\u000a\u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u043c \u043c\u043e\u0440\u0435 \u0438 \u0410\u0434\u0435\u043d\u0441\u043a\u043e\u043c \u0437\u0430\u043b\u0438\u0432\u0435, \u0437\u0430\u044f\u0432\u043b\u044f\u044f \u000d\u000a\u043e \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0435 \u043f\u0430\u043b\u0435\u0441\u0442\u0438\u043d\u0446\u0435\u0432. \u041f\u043e\u0441\u043b\u0435 \u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u000d\u000a\u043e\u0433\u043d\u044f \u043c\u0435\u0436\u0434\u0443 \u0418\u0437\u0440\u0430\u0438\u043b\u0435\u043c \u0438 \u0425\u0410\u041c\u0410\u0421 \u0432 \u043d\u044b\u043d\u0435\u0448\u043d\u0435\u043c \u000d\u000a\u043e\u043a\u0442\u044f\u0431\u0440\u0435 \u043b\u0438\u0434\u0435\u0440 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u044f \u0440\u0430\u0441\u043f\u043e\u0440\u044f\u0434\u0438\u043b\u0441\u044f \u000d\u000a\u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0443\u0434\u0430\u0440\u044b, \u043f\u043e\u043a\u0430 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u0435 \u000d\u000a\u0441\u043e\u0431\u043b\u044e\u0434\u0430\u0435\u0442\u0441\u044f. \u041d\u0430 \u043f\u0440\u043e\u0448\u043b\u043e\u0439 \u043d\u0435\u0434\u0435\u043b\u0435 \u043d\u0430\u0447\u0430\u043b\u044c\u043d\u0438\u043a \u000d\u000a\u0448\u0442\u0430\u0431\u0430 \u0445\u0443\u0441\u0438\u0442\u043e\u0432 \u042e\u0441\u0443\u0444 \u0430\u043b\u044c-\u041c\u0430\u0434\u0430\u043d\u0438 \u0441\u043e\u043e\u0431\u0449\u0438\u043b \u000d\u000a\u0425\u0410\u041c\u0410\u0421, \u0447\u0442\u043e \u043f\u0430\u0443\u0437\u0430 \u0432 \u0430\u0442\u0430\u043a\u0430\u0445 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f, \u000d\u000a\u043d\u043e \u0443\u0434\u0430\u0440\u044b \u043c\u043e\u0433\u0443\u0442 \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u0438\u0442\u044c\u0441\u044f \u043f\u0440\u0438 \u043d\u043e\u0432\u043e\u0439 \u000d\u000a\u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438 \u0432 \u0413\u0430\u0437\u0435.\u000d\u000a05 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 14\u201321 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438\u000d\u000a\u0421\u0428\u0410 \u0431\u0443\u0434\u0443\u0442 \u043f\u0440\u043e\u0434\u0430\u0432\u0430\u0442\u044c \u043f\u043e\u043b\u0443\u043f\u0440\u043e\u0432\u043e\u0434\u043d\u0438\u043a\u0438 \u0434\u0432\u0443\u043c \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c \u0432 \u041e\u0410\u042d \u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438\u000d\u000a\u0421\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u0430\u044f \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u043b\u0443\u043f\u0440\u043e\u0432\u043e\u0434\u043d\u0438\u043a\u043e\u0432 \u0434\u043e\u043b\u0436\u043d\u0430 \u0431\u044b\u0442\u044c \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u0430 35 \u0442\u044b\u0441. \u0447\u0438\u043f\u043e\u0432 Nvidia \u000d\u000aBlackwell.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u0421\u0428\u0410 \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u043b\u043e \u000d\u000a\u043f\u0440\u043e\u0434\u0430\u0436\u0443 \u043d\u043e\u0432\u0435\u0439\u0448\u0438\u0445 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0445 \u000d\u000a\u043f\u043e\u043b\u0443\u043f\u0440\u043e\u0432\u043e\u0434\u043d\u0438\u043a\u043e\u0432 \u0434\u0432\u0443\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u000d\u000a\u0437\u0430\u043d\u0438\u043c\u0430\u044e\u0442\u0441\u044f \u0418\u0418-\u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0430\u043c\u0438, \u2014  \u044d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u043e\u0439 \u000d\u000aG42 \u0438 \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 Humain. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a\u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u0432\u0435\u0434\u043e\u043c\u0441\u0442\u0432\u0430.\u000d\u000a\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f\u000d\u000a\u041f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0430\u044f \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u0421\u0428\u0410 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u000d\u000a\u0443\u0436\u0435\u0441\u0442\u043e\u0447\u0438\u043b\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u000d\u000a\u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u043b\u0430 \u0434\u043e\u0441\u0442\u0443\u043f \u000d\u000a\u043a \u0432\u044b\u0441\u043e\u043a\u043e\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u0447\u0438\u043f\u0430\u043c \u000d\u000a\u0434\u043b\u044f \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u043e\u0432, \u043f\u0440\u0435\u0436\u0434\u0435 \u000d\u000a\u0432\u0441\u0435\u0433\u043e \u041a\u0438\u0442\u0430\u044f.\u000d\u000a#\u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0438\u000d\u000a2 \u0434\u0435\u043a\u0430\u0431\u0440\u044f, \u041d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0435\u043d\u044c \u041e\u0410\u042d\u000d\u000a\u042d\u0442\u043e \u043e\u0434\u0438\u043d \u0438\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u043e\u0432, \u043f\u043e\u0441\u0432\u044f\u0449\u0435\u043d\u043d\u044b\u0439 \u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u044e \u0444\u0435\u0434\u0435\u0440\u0430\u0446\u0438\u0438.\u000d\u000a06 09","\u041a\u0438\u0442\u0430\u0439 14\u201321 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0444\u0438\u043d\u0430\u043d\u0441\u044b #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aChina Hongqiao Group \u043f\u0440\u0438\u0432\u043b\u0435\u043a\u043b\u0430 $1,5 \u043c\u043b\u0440\u0434 \u000d\u000a\u043e\u0442 \u043f\u0440\u043e\u0434\u0430\u0436\u0438 \u0430\u043a\u0446\u0438\u0439\u000d\u000a\u0421\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u044f\u0442 \u043d\u0430 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u0438 \u043f\u043e\u0433\u0430\u0448\u0435\u043d\u0438\u0435 \u0434\u043e\u043b\u0433\u043e\u0432.\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0447\u0430\u0441\u0442\u043d\u044b\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u000d\u000a\u0432 \u041a\u0438\u0442\u0430\u0435 China Hongqiao Group 400 \u043c\u043b\u043d \u000d\u000a\u0430\u043a\u0446\u0438\u0439 \u0441 \u0434\u0438\u0441\u043a\u043e\u043d\u0442\u043e\u043c 9,6% \u0438 \u043f\u0440\u0438\u0432\u043b\u0435\u043a \u043e\u043a\u043e\u043b\u043e \u2028\u000d\u000a$1,5 \u043c\u043b\u0440\u0434. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0431\u044f\u0437\u0430\u043b\u0430\u0441\u044c \u043d\u0435 \u043f\u0440\u043e\u0432\u043e\u0434\u0438\u0442\u044c \u000d\u000a\u043d\u043e\u0432\u044b\u0435 \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 90 \u0434\u043d\u0435\u0439. \u000d\u000a\u041f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u044b\u0435 \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u043f\u043e\u0439\u0434\u0443\u0442 \u043d\u0430 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u000d\u000a\u043f\u0440\u043e\u0434\u0430\u043b\u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u0432 \u041a\u0438\u0442\u0430\u0435 \u0438 \u0437\u0430 \u0440\u0443\u0431\u0435\u0436\u043e\u043c \u2028\u000d\u000a\u0438 \u043d\u0430 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0434\u043e\u043b\u0433\u043e\u0432.\u000a\u000d\u000a\u0421\u0434\u0435\u043b\u043a\u0443 \u0441\u043e\u043f\u0440\u043e\u0432\u043e\u0436\u0434\u0430\u043b\u0438 UBS, China Securities \u000d\u000aInternational \u0438 CMB International. \u0420\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u000d\u000a\u0441\u0442\u0430\u043b\u043e \u0442\u0440\u0435\u0442\u044c\u0438\u043c \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u043d\u0430 \u0413\u043e\u043d\u043a\u043e\u043d\u0433\u0441\u043a\u043e\u0439 \u000d\u000a\u0431\u0438\u0440\u0436\u0435 \u0432 \u044d\u0442\u043e\u043c \u0433\u043e\u0434\u0443 \u043f\u043e\u0441\u043b\u0435 \u0441\u0434\u0435\u043b\u043e\u043a BYD \u0438 Xiaomi.\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u041a\u043e\u043d\u0433\u0440\u0435\u0441\u0441 \u0421\u0428\u0410 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442 \u0443\u0447\u0430\u0441\u0442\u0438\u0435 Morgan Stanley \u000d\u000a\u0432 IPO Zijin Gold\u000d\u000a\u0411\u0430\u043d\u043a \u043f\u043e\u0434\u043e\u0437\u0440\u0435\u0432\u0430\u044e\u0442 \u0432 \u043e\u0431\u0445\u043e\u0434\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439 \u043f\u0440\u043e\u0442\u0438\u0432 \u043c\u0430\u0442\u0435\u0440\u0438\u043d\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438. \u000d\u000a\u041a\u043e\u043c\u0438\u0442\u0435\u0442 \u041f\u0430\u043b\u0430\u0442\u044b \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u0421\u0428\u0410 \u000d\u000a \u0443 Morgan Stanley \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b \u043e \u0435\u0433\u043e \u000d\u000a\u0440\u043e\u043b\u0438 \u0432 IPO \u0437\u043e\u043b\u043e\u0442\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 Zijin Gold \u000d\u000a\u0432 \u0413\u043e\u043d\u043a\u043e\u043d\u0433\u0435. \u041f\u0440\u0438\u0447\u0438\u043d\u0430 \u0432 \u0442\u043e\u043c, \u0447\u0442\u043e \u043c\u0430\u0442\u0435\u0440\u0438\u043d\u0441\u043a\u0430\u044f \u000d\u000a\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0439, Zijin Mining, \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u000d\u000a\u0432 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u043c \u0447\u0435\u0440\u043d\u043e\u043c \u0441\u043f\u0438\u0441\u043a\u0435 \u0438\u0437 \u0437\u0430 \u000d\u000a\u043f\u043e\u0434\u043e\u0437\u0440\u0435\u043d\u0438\u0439 \u0432 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u044f\u0445 \u043f\u0440\u0430\u0432 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430 \u000d\u000a\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0438 \u043d\u0430 \u0435\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u0445 \u000d\u000a\u043f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0442\u0440\u0443\u0434\u0430 \u0443\u0439\u0433\u0443\u0440\u043e\u0432.\u000a\u000d\u000a\u041a\u043e\u043c\u0438\u0442\u0435\u0442 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u043a\u0443 \u000d\u000a\u043f\u043e \u043e\u0446\u0435\u043d\u043a\u0435 \u0440\u0438\u0441\u043a\u043e\u0432 \u0438 \u0441\u0432\u044f\u0437\u044f\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0441 \u041a\u041f\u041a, \u000d\u000a\u0437\u0430\u043f\u0440\u043e\u0441\u0438\u043b\u000d\u000a\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u043c \u0438 \u0432\u043e\u0435\u043d\u043d\u044b\u043c\u0438 \u041a\u041d\u0420. \u041c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044b \u000d\u000a\u0434\u043e\u043b\u0436\u043d\u044b \u0431\u044b\u0442\u044c \u043f\u0435\u0440\u0435\u0434\u0430\u043d\u044b \u0434\u043e 27 \u043d\u043e\u044f\u0431\u0440\u044f.\u000a\u000d\u000aIPO Zijin Gold \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u043f\u0440\u0438\u043d\u0435\u0441\u043b\u043e \u043e\u043a\u043e\u043b\u043e \u000d\u000a$3,2 \u043c\u043b\u0440\u0434, \u0435\u0433\u043e \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0442\u043e\u0440\u0430\u043c\u0438 \u0432\u044b\u0441\u0442\u0443\u043f\u0438\u043b\u0438 \u000d\u000aMorgan Stanley \u0438 CITIC Securities. Zijin Mining \u000d\u000a\u0432 2024 \u0433\u043e\u0434\u0443 \u043f\u0440\u043e\u0438\u0437\u0432\u0435\u043b\u0430 40,4 \u0442\u043e\u043d\u043d\u044b \u0437\u043e\u043b\u043e\u0442\u0430 \u000d\u000a\u0438 \u0430\u043a\u0442\u0438\u0432\u043d\u043e \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u043b\u0430 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0435 \u0430\u043a\u0442\u0438\u0432\u044b, \u0432 \u0442\u043e\u043c \u000d\u000a\u0447\u0438\u0441\u043b\u0435 \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u043b\u0430 \u0440\u0443\u0434\u043d\u0438\u043a \u00ab\u0420\u0430\u0439\u0433\u043e\u0440\u043e\u0434\u043e\u043a\u00bb \u000d\u000a\u0432 \u041a\u0430\u0437\u0430\u0445\u0441\u0442\u0430\u043d\u0435 \u0437\u0430 $1,2 \u043c\u043b\u0440\u0434.\u000d\u000a07 09","\u041a\u0438\u0442\u0430\u0439 14\u201321 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0444\u0438\u043d\u0430\u043d\u0441\u044b #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aGlencore \u043c\u043e\u0436\u0435\u0442 \u0432\u043b\u043e\u0436\u0438\u0442\u044c\u0441\u044f \u0432 IPO Chuangxin Industries\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u044b\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u044b \u0433\u043e\u0442\u043e\u0432\u044b \u0432\u044b\u043a\u0443\u043f\u0438\u0442\u044c \u043e\u043a\u043e\u043b\u043e \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u044b \u0432\u044b\u043f\u0443\u0441\u043a\u0430.\u000d\u000aGlencore \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 IPO \u000d\u000a\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f Chuangxin \u000d\u000aIndustries \u0432 \u0413\u043e\u043d\u043a\u043e\u043d\u0433\u0435. \u0412 \u0447\u0438\u0441\u043b\u0435 \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u0435\u0439 \u0442\u0430\u043a\u0436\u0435 \u0430\u0437\u0438\u0430\u0442\u0441\u043a\u0438\u0439 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440 Hillhouse \u000d\u000aInvestment \u0438 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0447\u0430\u0441\u0442\u043d\u044b\u0439 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u041a\u0438\u0442\u0430\u0435 China \u000d\u000aHongqiao Group.\u000d\u000a\u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u041a\u0440\u0443\u043f\u043d\u044b\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u044b \u0433\u043e\u0442\u043e\u0432\u044b \u0432\u044b\u043a\u0443\u043f\u0438\u0442\u044c \u000d\u000a\u0434\u043e \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u044b \u043e\u0431\u044a\u0435\u043c\u0430 \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u043f\u0440\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0438 \u000d\u000a\u0443\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f \u0430\u043a\u0446\u0438\u0439 \u0432 \u043e\u0433\u043e\u0432\u043e\u0440\u0435\u043d\u043d\u044b\u0439 \u0441\u0440\u043e\u043a. \u041e\u0431\u044a\u0435\u043c \u000d\u000aIPO \u043c\u043e\u0436\u0435\u0442 \u0434\u043e\u0441\u0442\u0438\u0447\u044c $700 \u043c\u043b\u043d, \u043e\u0434\u043d\u0430\u043a\u043e \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u000d\u000a\u0441\u0434\u0435\u043b\u043a\u0438 \u0435\u0449\u0435 \u043e\u0431\u0441\u0443\u0436\u0434\u0430\u044e\u0442\u0441\u044f.\u000a\u000d\u000a\u041e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0442\u043e\u0440\u044b \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u2014 China International \u000d\u000aCapital \u0438 Huatai Securities.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u043f\u0440\u0438\u0437\u0432\u0430\u043b\u0438 \u000d\u000a\u0432\u043b\u0430\u0441\u0442\u0438 \u0441\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u044e\u000d\u000a\u0421\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u0441\u043f\u0440\u043e\u0441\u0430 \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0430\u0432\u0442\u043e\u043f\u0440\u043e\u043c\u0430 \u0432\u044b\u0437\u044b\u0432\u0430\u0435\u0442 \u0440\u0438\u0441\u043a \u043f\u0435\u0440\u0435\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430.\u000d\u000a\u0410\u0441\u0441\u043e\u0446\u0438\u0430\u0446\u0438\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043d\u0438\u043a\u0435\u043b\u044f \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u000d\u000a \u043e \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u043a\u0438 \u000d\u000a\u043e\u0442\u0440\u0430\u0441\u043b\u0435\u0432\u043e\u0439 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0438 \u0438\u0437 \u0437\u0430 \u0437\u0430\u043c\u0435\u0434\u043b\u0435\u043d\u0438\u044f \u0441\u043f\u0440\u043e\u0441\u0430 \u000d\u000a\u043d\u0430 \u043d\u0438\u043a\u0435\u043b\u044c \u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439. \u041f\u0440\u043e\u0433\u043d\u043e\u0437\u044b, \u000d\u000a\u043e\u0431\u0435\u0449\u0430\u0432\u0448\u0438\u0435 \u043f\u0435\u0440\u0435\u0445\u043e\u0434 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u043e\u0442 LFP \u043a\u0430\u0442\u043e\u0434\u043e\u0432 \u000d\u000a\u043a \u043d\u0438\u043a\u0435\u043b\u044c\u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0449\u0438\u043c NMC, \u043d\u0435 \u043e\u043f\u0440\u0430\u0432\u0434\u0430\u043b\u0438\u0441\u044c, \u000d\u000a\u0430 \u0434\u043e\u043b\u044f \u0441\u043f\u0440\u043e\u0441\u0430 \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439 \u000d\u000a\u0441\u043d\u0438\u0437\u0438\u043b\u0430\u0441\u044c \u0441 37% \u0434\u043e 18%.\u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u0430\u000d\u000a\u041f\u0440\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0438 \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f LFP \u000d\u000a\u0438 \u043f\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0445 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439 \u0440\u0438\u0441\u043a \u000d\u000a\u043f\u0435\u0440\u0435\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u0440\u0430\u0441\u0442\u0438. \u0412 \u0441\u0442\u0440\u0430\u043d\u0435 \u000d\u000a\u0443\u0436\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442 12 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0449\u0438\u0445 \u000d\u000aHPAL-\u043f\u0440\u043e\u0446\u0435\u0441\u0441 \u0434\u043b\u044f \u0432\u044b\u043f\u0443\u0441\u043a\u0430 \u0441\u044b\u0440\u044c\u044f \u0434\u043b\u044f \u0431\u0430\u0442\u0430\u0440\u0435\u0439. \u000d\u000a\u0410\u0441\u0441\u043e\u0446\u0438\u0430\u0446\u0438\u044f \u043f\u0440\u0438\u0437\u0432\u0430\u043b\u0430 \u0432\u043b\u0430\u0441\u0442\u0438 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0442\u044c \u000d\u000a\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0441\u043f\u0440\u043e\u0441\u0430.\u000d\u000a08 09","\u041a\u0438\u0442\u0430\u0439 14\u201321 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aGanfeng Lithium \u043e\u0436\u0438\u0434\u0430\u0435\u0442 30\u201340-\u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043d\u043e\u0433\u043e \u0440\u043e\u0441\u0442\u0430 \u000d\u000a\u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043b\u0438\u0442\u0438\u0439 \u0432 2026 \u0433\u043e\u0434\u0443\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u0440\u043e\u0441\u0442 \u0446\u0435\u043d \u0434\u043e $28 \u0442\u044b\u0441. \u0437\u0430 \u0442\u043e\u043d\u043d\u0443\u000d\u000a\u0413\u043b\u0430\u0432\u0430 Ganfeng Lithium \u041b\u0438 \u041b\u044f\u043d\u0431\u0438\u043d\u044c , \u000d\u000a\u0447\u0442\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0438 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u043f\u0440\u0438\u0432\u0435\u043b\u043e \u043a \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044e \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0430 \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043b\u0438\u0442\u0438\u0439 \u0432 2025 \u0433\u043e\u0434\u0443 \u0434\u043e 1,55 \u043c\u043b\u043d \u0442\u043e\u043d\u043d. \u000d\u000a\u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u043c\u043e\u0436\u0435\u0442 \u0434\u043e\u0441\u0442\u0438\u0447\u044c \u2028\u000d\u000a1,7 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u0447\u0442\u043e \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442 \u043f\u0440\u043e\u0444\u0438\u0446\u0438\u0442 \u043e\u043a\u043e\u043b\u043e \u2028\u000d\u000a200 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b \u0412 2026 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0436\u0438\u0434\u0430\u0435\u0442 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044f \u000d\u000a\u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043a\u0430\u0440\u0431\u043e\u043d\u0430\u0442 \u043b\u0438\u0442\u0438\u044f \u0434\u043e 1,9 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043f\u0440\u0438 \u000d\u000a\u0440\u043e\u0441\u0442\u0435 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043d\u0430 250 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d. \u042d\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u000d\u000a\u043f\u043e\u0434\u043d\u044f\u0442\u044c \u0446\u0435\u043d\u044b \u0434\u043e 150\u2013200 \u0442\u044b\u0441. \u044e\u0430\u043d\u0435\u0439 \u0437\u0430 \u0442\u043e\u043d\u043d\u0443 \u000d\u000a($21\u201328 \u0442\u044b\u0441.).\u000d\u000a#\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0411\u0438\u0440\u0436\u0430 \u0413\u0443\u0430\u043d\u0447\u0436\u043e\u0443 GFEX \u043d\u0430\u0447\u043d\u0435\u0442 \u0440\u0430\u0441\u043a\u0440\u044b\u0432\u0430\u0442\u044c \u0437\u0430\u043f\u0430\u0441\u044b \u000d\u000a\u043f\u043b\u0430\u0442\u0438\u043d\u044b \u0438 \u043f\u0430\u043b\u043b\u0430\u0434\u0438\u044f\u000d\u000a\u041f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u0438 \u0431\u0443\u0434\u0443\u0442 \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u044b\u043c\u0438 \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u0442\u043e\u0440\u0433\u043e\u0432 \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u0430\u043c\u0438.\u000d\u000aGFEX \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u043e \u0440\u0430\u0441\u043a\u0440\u044b\u0432\u0430\u0442\u044c \u0434\u0430\u043d\u043d\u044b\u0435 \u000d\u000a\u043e \u0437\u0430\u043f\u0430\u0441\u0430\u0445 \u043f\u043b\u0430\u0442\u0438\u043d\u044b \u0438 \u043f\u0430\u043b\u043b\u0430\u0434\u0438\u044f \u043d\u0430 \u0441\u043a\u043b\u0430\u0434\u0430\u0445 \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u0442\u043e\u0440\u0433\u043e\u0432 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u043c\u0438 \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u0430\u043c\u0438. \u000d\u000a\u042d\u0442\u043e \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442 \u043f\u0440\u043e\u0437\u0440\u0430\u0447\u043d\u043e\u0441\u0442\u044c \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u0438\u0437 \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0440\u044b\u043d\u043a\u043e\u0432, \u0433\u0434\u0435 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u0430\u044f \u000d\u000a\u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u043f\u043e \u0437\u0430\u043f\u0430\u0441\u0430\u043c \u0441\u0435\u0439\u0447\u0430\u0441 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442.\u000d\u000a\u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0420\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440 \u0443\u0436\u0435 \u043e\u0434\u043e\u0431\u0440\u0438\u043b \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044e \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u0432, \u000d\u000a\u043e\u0434\u043d\u0430\u043a\u043e \u0434\u0430\u0442\u0443 \u0441\u0442\u0430\u0440\u0442\u0430 \u043f\u043e\u043a\u0430 \u043d\u0435 \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0438. \u041f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u0431\u0443\u0434\u0443\u0442 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b \u043a\u0430\u043a \u0432 \u0441\u043b\u0438\u0442\u043a\u0430\u0445, \u0442\u0430\u043a \u0438 \u0432 \u043f\u043e\u0440\u043e\u0448\u043a\u0435, \u000d\u000a\u0447\u0442\u043e \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u043e \u0434\u043b\u044f \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0431\u0438\u0440\u0436.\u000a\u000d\u000aGFEX \u0441\u043e\u0437\u0434\u0430\u043d\u0430 \u0432 2021 \u0433\u043e\u0434\u0443, \u0440\u0430\u043d\u0435\u0435 \u043d\u0430 \u043d\u0435\u0439 \u000d\u000a\u043f\u043e\u044f\u0432\u0438\u043b\u0438\u0441\u044c \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u044b \u043d\u0430 \u043a\u0440\u0435\u043c\u043d\u0438\u0439 \u0438 \u043b\u0438\u0442\u0438\u0439.\u000d\u000a09 09"]